-- sql
WITH _hq_raw AS (SELECT tuple(created_at, amount_cents, NULL) AS _hq_row FROM analytics.orders WHERE tenant_id = ?),
_hq_source AS (SELECT toDateTime64(assumeNotNull(tupleElement(_hq_row, 1)), 9, 'UTC') AS _hq_time, tupleElement(_hq_row, 2) AS _hq_v0, tupleElement(_hq_row, 3) AS _hq_a0 FROM _hq_raw WHERE isNotNull(tupleElement(_hq_row, 1))),
_hq_bounds AS (SELECT parseDateTime64BestEffort(?, 9, timezoneOf(assumeNotNull((SELECT _hq_time FROM _hq_source LIMIT 0)))) AS _hq_lower, parseDateTime64BestEffort(?, 9, timezoneOf(assumeNotNull((SELECT _hq_time FROM _hq_source LIMIT 0)))) AS _hq_upper, toStartOfDay(_hq_lower) AS _hq_first, toStartOfDay(_hq_upper) AS _hq_last),
_hq_series AS (SELECT addDays(_hq_first, arrayJoin(range(toUInt64(dateDiff('day', _hq_first, _hq_last) + 1 + 0 + 0 + throwIf(arrayExists(_hq_calendar_index -> addDays(_hq_first, _hq_calendar_index + 1) <= addDays(_hq_first, _hq_calendar_index), range(toUInt64(greatest(1, dateDiff('day', _hq_first, _hq_last) + 1 + 0 + throwIf(_hq_lower > _hq_upper, 'Window measure time range must be non-empty and ordered.'))))), 'Time range crosses a skipped local calendar bucket; use a UTC time key for this range.') + throwIf(_hq_lower > _hq_upper, 'Window measure time range must be non-empty and ordered.'))))) AS _hq_period FROM _hq_bounds),
_hq_scanned AS (SELECT * FROM _hq_source CROSS JOIN _hq_bounds WHERE (_hq_time < addDays(_hq_last, 1))),
_hq_skeleton AS (SELECT * FROM _hq_series),
_hq_fan0 AS (SELECT *, addDays(toStartOfDay(_hq_time), arrayJoin(range(toUInt64(dateDiff('day', toStartOfDay(_hq_time), addDays(toStartOfDay(_hq_time), 7)) + throwIf(dateDiff('day', toStartOfDay(_hq_time), addDays(toStartOfDay(_hq_time), 7)) > 1000, 'A window row contributes to more than 1000 buckets.') + throwIf(arrayExists(_hq_calendar_index -> addDays(toStartOfDay(_hq_time), _hq_calendar_index + 1) <= addDays(toStartOfDay(_hq_time), _hq_calendar_index), range(toUInt64(greatest(1, dateDiff('day', toStartOfDay(_hq_time), addDays(toStartOfDay(_hq_time), 7)) + throwIf(dateDiff('day', toStartOfDay(_hq_time), addDays(toStartOfDay(_hq_time), 7)) > 1000, 'A window row contributes to more than 1000 buckets.'))))), 'Time range crosses a skipped local calendar bucket; use a UTC time key for this range.'))))) AS _hq_period FROM _hq_scanned),
_hq_agg0 AS (SELECT _hq_period, toNullable(sumOrNull(_hq_v0)) AS _hq_m0 FROM _hq_fan0 WHERE _hq_period BETWEEN _hq_first AND _hq_last AND _hq_time >= subtractDays(addDays(_hq_period, 1), 7) GROUP BY _hq_period),
_hq_fan1 AS (SELECT *, greatest(toStartOfDay(_hq_time), _hq_first) AS _hq_period FROM _hq_scanned),
_hq_agg1 AS (SELECT _hq_period, toNullable(sumOrNull(_hq_v0)) AS _hq_m1 FROM _hq_fan1 WHERE _hq_period BETWEEN _hq_first AND _hq_last GROUP BY _hq_period),
_hq_values AS (SELECT s._hq_period AS period, m0._hq_m0 AS `rolling`, sumOrNull(m1._hq_m1) OVER (ORDER BY s._hq_period ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS `running` FROM _hq_skeleton AS s LEFT JOIN _hq_agg0 AS m0 ON s._hq_period = m0._hq_period LEFT JOIN _hq_agg1 AS m1 ON s._hq_period = m1._hq_period),
_hq_result AS (SELECT `period`, (`rolling` / NULLIF(`running`, 0)) AS `rollingShare` FROM _hq_values UNION ALL SELECT NULL AS `period`, NULL AS `rollingShare` FROM _hq_bounds WHERE 0 + 0 + throwIf(arrayExists(_hq_calendar_index -> addDays(_hq_first, _hq_calendar_index + 1) <= addDays(_hq_first, _hq_calendar_index), range(toUInt64(greatest(1, dateDiff('day', _hq_first, _hq_last) + 1 + 0 + throwIf(_hq_lower > _hq_upper, 'Window measure time range must be non-empty and ordered.'))))), 'Time range crosses a skipped local calendar bucket; use a UTC time key for this range.') + throwIf(_hq_lower > _hq_upper, 'Window measure time range must be non-empty and ordered.') + 0 = 1) SELECT `period`, `rollingShare` FROM _hq_result ORDER BY `period` ASC

